const key = $env.JELLYSEERR_API_KEY;
if (!key) throw new Error('JELLYSEERR_API_KEY is not configured');

const response = await this.helpers.httpRequest({
  method: 'GET',
  url: 'http://127.0.0.1:8423/api/v1/request',
  qs: {take: 100, skip: 0, sort: 'added'},
  headers: {'X-Api-Key': key},
  json: true,
});

const state = $getWorkflowStaticData('global');
const current = Object.fromEntries(
  (response.results ?? []).map((request) => [
    String(request.id),
    {
      requestStatus: request.status,
      mediaStatus: request.media?.status ?? null,
      type: request.type,
      tmdbId: request.media?.tmdbId ?? null,
      requester: request.requestedBy?.displayName ?? request.requestedBy?.email ?? 'unknown',
      mediaUrl: request.media?.mediaUrl ?? null,
    },
  ]),
);

if (!state.requests) {
  state.requests = current;
  return [];
}

const requestLabel = {1: 'pending approval', 2: 'approved', 3: 'declined', 4: 'failed', 5: 'completed'};
const mediaLabel = {1: 'unknown', 2: 'pending', 3: 'processing', 4: 'partly available', 5: 'available'};
const changes = [];
for (const [id, item] of Object.entries(current)) {
  const previous = state.requests[id];
  if (!previous) {
    changes.push({id, item, text: `new request, ${requestLabel[item.requestStatus] ?? item.requestStatus}`});
  } else if (previous.requestStatus !== item.requestStatus || previous.mediaStatus !== item.mediaStatus) {
    changes.push({
      id,
      item,
      text: `${requestLabel[previous.requestStatus] ?? previous.requestStatus} to ${requestLabel[item.requestStatus] ?? item.requestStatus}; media ${mediaLabel[item.mediaStatus] ?? item.mediaStatus}`,
    });
  }
}
if (!changes.length) return [];

return [{json: {nextState: current, changes}}];

const nextState = $('Check request changes').first().json.nextState;
const state = $getWorkflowStaticData('global');
state.requests = nextState;
return $input.all();

// Only "it is ready to watch". Approvals, declines and processing steps are
// bookkeeping; becoming available is the one transition that asks you to do
// something. The bookkeeping used to go out as a mail on every change, polled
// every ten minutes, which is how this workflow alone could spend most of the
// twenty outgoing mails a day Migadu allows. Jellyseerr's own request list is
// the record of those steps.
const AVAILABLE = 5;
const { changes = [], nextState } = $input.first().json;

const ready = changes.filter((c) => c.item?.mediaStatus === AVAILABLE);
if (ready.length === 0) {
  // Nothing goes to the spine, so "Commit notification state" never runs:
  // record the bookkeeping here, or the same steps are re-detected forever.
  $getWorkflowStaticData('global').requests = nextState;
  return [];
}

const key = $env.JELLYSEERR_API_KEY;

// /api/v1/request does not carry a title -- only tmdbId -- so a readable name
// costs one lookup per item. That is affordable here precisely because this
// runs only for things that just became available, which is almost always
// none or one, rather than for all hundred tracked requests.
//
// MovieDetails carries `title` and TvDetails carries `name`; both confirmed
// against the jellyseerr-api.yml shipped with the package rather than assumed.
const titleOf = async (item, id) => {
  const fallback = `${item?.type === "tv" ? "Serie" : "Film"} #${item?.tmdbId ?? id}`;
  if (!key || !item?.tmdbId) return fallback;
  try {
    const details = await this.helpers.httpRequest({
      method: "GET",
      url: `http://127.0.0.1:8423/api/v1/${item.type === "tv" ? "tv" : "movie"}/${item.tmdbId}`,
      headers: { "X-Api-Key": key },
      json: true,
    });
    return details?.title || details?.name || fallback;
  } catch {
    // "Film #12345 ist verfügbar" is worth far more than no notification at
    // all, so a lookup that fails degrades to the id instead of throwing and
    // losing the news entirely.
    return fallback;
  }
};

const labels = [];
for (const change of ready) labels.push(await titleOf(change.item, change.id));

return [
  {
    json: {
      source: "jellyseerr",
      severity: "info",
      title: labels.length === 1 ? `${labels[0]} ist verfügbar` : `${labels.length} Anfragen verfügbar`,
      message: labels.join("\n"),
      // Per media id, so the same title turning available twice (a re-grab, a
      // season completing again) cannot push twice inside the window.
      fingerprint: `jellyseerr:available:${ready.map((c) => c.id).sort().join(",")}`,
      url: ready[0]?.item?.mediaUrl ?? null,
    },
  },
];
